"use client";
import * as React from "react";
import { motion } from "motion/react";
import { cn } from "@/lib/utils";
import {
  bentoTilePath,
  validateBento,
  type BentoLayout,
  type BentoTile,
  type BentoVariant,
} from "@/lib/cojeev/bento-layout";
import { useMotionVisibility } from "@/lib/cojeev-motion/use-motion-visibility";
import { assignMotionRef } from "@/lib/cojeev-motion/refs";
export type { BentoLayout, BentoTile, BentoVariant } from "@/lib/cojeev/bento-layout";
export type BentoGridProps = React.ComponentProps<"div"> & {
  layout: BentoLayout;
  variant: BentoVariant;
  renderTile?: (tile: BentoTile) => React.ReactNode;
};
export function BentoGrid({
  layout,
  variant = "classic",
  renderTile,
  className,
  style,
  ref,
  ...props
}: BentoGridProps) {
  const host = React.useRef<HTMLDivElement>(null),
    { enabled, inView } = useMotionVisibility(host);
  const attach = React.useCallback(
    (node: HTMLDivElement | null) => {
      host.current = node;
      const cleanup = assignMotionRef(ref, node);
      return () => {
        host.current = null;
        cleanup();
      };
    },
    [ref],
  );
  const geometry = layout.tiles
    .map((t) => `${t.x},${t.y},${t.width},${t.height}`)
    .join(";");
  const error = validateBento(layout);
  if (error)
    return (
      <div
        {...props}
        ref={attach}
        role="alert"
        className={className}
        style={style}
      >
        {error}
      </div>
    );
  return (
    <div
      {...props}
      ref={attach}
      data-slot="bento-grid"
      data-variant={variant}
      className={cn("v-bento", className)}
      style={
        {
          "--bento-columns": layout.columns,
          "--bento-rows": layout.rows,
          ...style,
        } as React.CSSProperties
      }
    >
      {variant === "interlock" && (
        <svg
          className="v-bento__paint"
          viewBox={`0 0 ${layout.columns} ${layout.rows}`}
          preserveAspectRatio="none"
          aria-hidden="true"
        >
          <g key={geometry}>
            {layout.tiles.map((tile, i) => (
              <motion.path
                key={`${tile.x},${tile.y}`}
                className={`v-bento__color-${i % 6}`}
                initial={false}
                animate={{ d: bentoTilePath(tile, layout) }}
                transition={{ duration: enabled && inView ? 0.3 : 0 }}
                vectorEffect="non-scaling-stroke"
              />
            ))}
          </g>
        </svg>
      )}
      {layout.tiles.map((tile, i) => (
        <div
          key={tile.id}
          data-bento-tile={tile.id}
          className={`v-bento__tile v-bento__color-${i % 6}`}
          style={{
            gridColumn: `${tile.x + 1} / span ${tile.width}`,
            gridRow: `${tile.y + 1} / span ${tile.height}`,
          }}
        >
          {renderTile ? (
            renderTile(tile)
          ) : (
            <>
              <span className="v-bento__number">
                {String(i + 1).padStart(2, "0")}
              </span>
              <span className="v-bento__label">{tile.label}</span>
            </>
          )}
        </div>
      ))}
    </div>
  );
}

@layer cojeev-states {
.v-bento {
  position: relative;
  isolation: isolate;
  display: grid;
  grid-template-columns: repeat(var(--bento-columns), minmax(0, 1fr));
  grid-template-rows: repeat(var(--bento-rows), minmax(88px, 1fr));
  gap: 10px;
  width: 100%;
  min-width: 0;
  color: var(--v-on-accent);
  container-type: inline-size;
}
.v-bento__tile {
  position: relative;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  gap: 16px;
  padding: 26px;
  min-width: 0;
  overflow-wrap: anywhere;
  border-radius: 20px;
  background: var(--bento-fill);
  color: var(--v-on-accent);
}
/* Default text scales with its usable tile width, after the safe paint inset.
   Custom tile renderers retain their own sizing and container ownership. */
.v-bento__tile:has(> .v-bento__label) {
  container-type: inline-size;
}
.v-bento__color-0 {
  --bento-fill: var(--v-pink);
}
.v-bento__color-1 {
  --bento-fill: var(--v-blue);
}
.v-bento__color-2 {
  --bento-fill: var(--v-yellow);
}
.v-bento__color-3 {
  --bento-fill: var(--v-olive);
}
.v-bento__color-4 {
  --bento-fill: var(--v-beige);
  color: var(--v-text);
}
.v-bento__color-5 {
  --bento-fill: var(--v-blue);
}
.v-bento__number {
  font-size: 11px;
  letter-spacing: 0.09em;
  line-height: 1.4;
  opacity: 0.65;
}
.v-bento__label {
  font-family: var(--font-display, inherit);
  font-size: clamp(16px, 12cqi, 30px);
  font-weight: 500;
  line-height: 1.15;
  letter-spacing: -0.025em;
  max-width: 18ch;
}
.v-bento__paint {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  overflow: visible;
  pointer-events: none;
  z-index: -1;
}
.v-bento__paint path {
  fill: var(--bento-fill);
  stroke: var(--v-canvas);
  stroke-width: 8;
  stroke-linejoin: round;
}
.v-bento[data-variant="interlock"] {
  gap: 0;
}
.v-bento[data-variant="interlock"] > .v-bento__tile {
  background: transparent;
  border-radius: 0;
  padding: 32px;
}
@media (max-width: 600px) {
  .v-bento[data-variant="interlock"] {
    gap: 12px;
  }
  .v-bento {
    display: flex;
    flex-direction: column;
    gap: 12px;
  }
  .v-bento__tile,
  .v-bento[data-variant="interlock"] > .v-bento__tile {
    min-height: 150px;
    padding: 24px;
    background: var(--bento-fill);
    border-radius: 20px;
  }
  .v-bento__paint {
    display: none;
  }
  .v-bento__label {
    font-size: 26px;
  }
  .v-bento[data-variant="interlock"] > .v-bento__tile {
    border-radius: 30px 18px 28px 20px;
  }
}

}
